/**
 * Compact, scientifically authentic showcase dataset extracted from
 * David Kolář's VŠCHT "Základy bioinformatiky" GH48 semestral project
 * (https://github.com/kolardavidcz/GH48).
 *
 * Preserves the real 29-taxon pruned IQ-TREE phylogeny, NCBI taxonomy,
 * MEME/FIMO motif bifurcation (MEME-23+ Actinomycetota + Coleoptera HGT vs.
 * MEME-25+ ancestral Bacillota + Fungi), HMMER PF02011 domtblout, MMseqs2
 * clusters, and reviewed UniProt/CAZy characterized GH48 enzymes.
 */

export interface PipelineStepSpec {
  step: number;
  title: string;
  tool: string;
  where: "browser" | "galaxy" | "external";
  externalUrl?: string;
  externalLabel?: string;
  summary: string;
  command: string;
  gh48Metric: string;
}

